L15_1 = "각 유닛은 <COLOR=#FFBC00>하나의 클래스를 보유</COLOR>하고 있으며, 각각 <COLOR=#FFBC00>상성</COLOR> 이 있습니다.\n유리한 상성의 클래스에겐 <COLOR=#FFBC00>입히는 피해량</COLOR>이 증가하고, <COLOR=#FFBC00>받는 피해는 감소</COLOR> 합니다."
