L5_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_BANLIST_1_DESC"
L6_1 = "최근 일정 기간 내의 픽률과 승리횟수를 분석하여, 밴 대상을 선정합니다.\n밴 선정은 매 주마다 진행하며, 선정되지 않은 유닛/함선은 밴 단계가 1감소합니다.\n\n<COLOR=#FFBC00>※ 밴 수량은 출시된 유닛 및 함선 수에 따라 증가합니다.</COLOR>"
