L14_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_BANLIST_2_DESC"
L15_1 = "유닛은 리더 보너스를 받을 수 없으며, 밴 단계만큼 출격 비용이 1씩, 최대 10까지 증가하고,\n능력치 패널티를 받게되며, 얼터니움 리액터의 해방 단계가 1단계씩 감소됩니다.\n함선은 밴 단계만큼 공격력, 체력 및 스킬 충전 속도가 -40%씩, 최대 80% 까지 감소합니다.\n<COLOR=#FFBC00>※브론즈 등급과 매칭된 게임은 밴이 적용되지 않습니다.</COLOR>"
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_BANLIST_2_DESC_VER2"
L16_1 = "밴 지정된 유닛은 시즌이 끝날때까지 편성이 금지됩니다.\n함선은 밴 단계만큼 공격력, 체력 및 스킬 충전 속도가 -40%씩, 최대 80% 까지 감소합니다."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_INFO_1_DESC"
L17_1 = "건틀렛에서는 <COLOR=#FFBC00>다른 유저와 대결</COLOR>할 수 있습니다."
