L17_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_MATCH_1_DESC"
L18_1 = "리그 목록에서 다른 유저를 선택해서 연습전을 치뤄볼 수 있습니다.\n연습전은 비동기식으로 이루어집니다.\n\n연습전을 통해서도 하루 일정량의 건틀렛 포인트를 획득할 수 있습니다.\n<COLOR=#FFBC00>※ 협력사와의 연습전에서는 획득할 수 없습니다.</COLOR>"
