L23_1 = "랭크전에서는 <COLOR=#FFBC00>실시간으로 대결</COLOR>할 수 있습니다.\n랭크전에서는 <COLOR=#FFBC00>승점</COLOR>이 계산되며, 자신과 비슷한 승점의 상대를 적으로 만납니다.\n승리하면 승점을 얻고, 패배하면 승점을 잃습니다."
