L27_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_RANK_2_DESC"
L28_1 = "랭크전에서 승리하면 건틀렛 포인트를 얻습니다.\n<COLOR=#FFBC00>건틀렛 포인트를 얻을 때 보상포인트가 소모</COLOR>되며, 모두 소진시 건틀렛 포인트를 얻을 수 없습니다.\n보상 포인트는 6시간마다 225씩 충전됩니다.\n\n<COLOR=#FFBC00>추가 보상포인트</COLOR>가 있다면, 건틀렛 포인트를 2배로 얻을 수 있습니다."
