L33_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_RANK_3_DESC_02"
L34_1 = "리그 보상은 매주, 그리고 시즌마다 주어집니다.\n자세한 보상 및 도움말은 리그 정보에서 확인할 수 있습니다."
