L36_1 = "전략전에서는 <COLOR=#FFBC00>비동기로 대전</COLOR>할 수 있습니다.\n<COLOR=#FFBC00>상대의 방어 소대</COLOR>와 전투하며, <COLOR=#FFBC00>전투는 자동으로 진행</COLOR>됩니다.\n승리하면 승점을 얻지만, 패배하면 승점을 잃습니다."
