L15_1 = "SI_PF_TUTORIAL_TEXUTRE_RAID_HELP_1_DESC"
L16_1 = "레이드 이벤트는 지부의 파견 미션을 완료한 후, 일정확률로 발생합니다.\n지부 레벨이 높을수록,  발생하는 레이드의 난이도가 높아집니다.\n내가 발견한 레이드는 월드맵에 노출되며, 탐색 현황을 통해 발견한 레이드를 관리 할 수 있습니다."
