L21_1 = "SI_PF_TUTORIAL_TEXUTRE_RAID_HELP_2_DESC"
L22_1 = "<COLOR=#FFBC00>지원요청을 활성화</COLOR>해 <COLOR=#FFBC00>다른 유저로부터 지원</COLOR>을 받거나, 다른 유저가 지원을 요청한 레이드에 참가할 수 있습니다.\n\n보스 토벌에 성공하면, 레이드 <COLOR=#FFBC00>참가가 모두 보상</COLOR>을 받습니다.\n<COLOR=#FFBC00>발견자</COLOR>이거나, <COLOR=#FFBC00>최고 피해</COLOR>를 입힌 경우 <COLOR=#FFBC00>특별한 보상</COLOR>을 받습니다."
