L20_1 = "SI_PF_TUTORIAL_TEXUTRE_UNIT_LIMITBREAK_1_DESC"
L21_1 = "유닛의 <COLOR=#FFBC00>빈 별 칸수</COLOR>만큼 한계 초월을 할 수 있습니다.\n한계초월시 <COLOR=#FFBC00>모든 능력치</COLOR>가 증가합니다.\n또한 <COLOR=#FFBC00>스킬 최대 레벨이 증가</COLOR>하며, 4번째 장비 슬롯이 개방되기도 합니다."
