L23_1 = "초월을 할 때는 <COLOR=#FFBC00>적성핵</COLOR>과 <COLOR=#FFBC00>크레딧</COLOR>이 필요합니다!\n높은 등급일수록 더 많은 적성핵과 특수적성핵, 더 많은 크레딧이 소모됩니다."
