L27_1 = "SI_PF_TUTORIAL_TEXUTRE_UNIT_LIMITBREAK_3_DESC"
L28_1 = "사원은 융합핵이나 동일 유닛을 이용하여 <COLOR=#FFBC00>한계 융합</COLOR>을 할 수 있습니다.\n<COLOR=#FFBC00>한계 융합</COLOR>할 때마다 <COLOR=#FFBC00>최대 레벨이 2 증가</COLOR>하고, <COLOR=#FFBC00>능력치 성장률이 2% 씩 증가</COLOR>합니다.\n<COLOR=#FFBC00>한계 융합</COLOR>은 <COLOR=#FFBC00>최대 다섯 번</COLOR>까지 가능합니다."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_PF_TUTORIAL_TEXUTRE_UNIT_LIMITBREAK_3_DESC_VER2"
L29_1 = "사원은 융합핵이나 융합핵 파편 또는 특수융합핵을 이용하여 <COLOR=#FFBC00>한계 융합</COLOR>을 할 수 있습니다.\n<COLOR=#FFBC00>한계 융합</COLOR>할 때마다 <COLOR=#FFBC00>최대 레벨이 2 증가</COLOR>하고, <COLOR=#FFBC00>능력치 성장률이 2% 씩 증가</COLOR>합니다.\n<COLOR=#FFBC00>한계 융합</COLOR>은 <COLOR=#FFBC00>최대 열 번</COLOR>까지 가능합니다."
L27_1[1] = L28_1
L27_1[2] = L29_1
