L13_1 = "SI_PF_TUTORIAL_TEXUTRE_UNIT_WEDDING_CONTRACT_1_DESC"
L14_1 = "사원이 회사에 가진 애정입니다.\n애사심이 가득 차면 <COLOR=#FFBC00>모든 능력치가 2%</COLOR>증가하며,\n종신 계약을 진행할 수 있습니다.\n\n애사심은 <COLOR=#FFBC00>전투에서 승리</COLOR>하면 소폭 증가하며,\n<COLOR=#FFBC00>연봉협상</COLOR>에 성공하면 크게 증가합니다.\n\n하지만 전투에서 패배하면 감소합니다."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_PF_TUTORIAL_TEXUTRE_UNIT_WEDDING_CONTRACT_2_TITLE"
L15_1 = "종신 계약"
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_PF_TUTORIAL_TEXUTRE_UNIT_WEDDING_CONTRACT_2_DESC"
L16_1 = "사원의 애사심이 100이 되면 종신 고용 계약을 할 수 있습니다.\n\n종신 계약한 사원은 <COLOR=#FFBC00>애사심이 감소하지 않으며, 추가 경험치를 획득</COLOR>합니다.\n가끔 <COLOR=#FFBC00>특별한 대화</COLOR>를 사장님께 건네기도 합니다."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_PF_TUTORIAL_TEXUTRE_UNIT_WEDDING_CONTRACT_3_TITLE"
L17_1 = "종신 계약"
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_PF_TUTORIAL_TEXUTRE_UNIT_WEDDING_CONTRACT_3_LIFETIME"
L18_1 = "종신 재직"
L16_1[1] = L17_1
L16_1[2] = L18_1
