L18_1 = "SI_PF_TUTORIAL_TEXUTRE_UNIT_WEDDING_CONTRACT_3_DESC"
L19_1 = "종신 계약은 <COLOR=#FFBC00>사장실</COLOR>에서 할 수 있으며, <COLOR=#FFBC00>종신고용 계약서</COLOR>가 필요합니다.\n\n도장을 찍기 전까지는 종신 계약이 완료되지 않습니다.\n도장은 신중하게 찍으세요."
L17_1[1] = L18_1
L17_1[2] = L19_1
