L20_1 = "SI_PF_TUTORIAL_TEXUTRE_WARFARE_ASSIST_1_DESC_01"
L21_1 = "<COLOR=#FFBC00>전투가 발생한 타일 1칸</COLOR>안에 \n<COLOR=#FFBC00>인접한 아군 소대</COLOR>가 있다면,\n<COLOR=#FFBC00>각 소대 리더</COLOR>들이 <COLOR=#FFBC00>어시스트로 참가</COLOR>합니다."
L19_1[1] = L20_1
L19_1[2] = L21_1
