L23_1 = "어시스트 소대의 리더들은 <COLOR=#FFBC00>출격 자원을 소비하지 않으며</COLOR>,\n<COLOR=#FFBC00>1회만 출격 가능</COLOR>합니다."
L21_1[1] = L22_1
L21_1[2] = L23_1
