L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_PF_TUTORIAL_TEXUTRE_WARFARE_AUTOPLAY_1_DESC"
L25_1 = "우측 상단의 <COLOR=#FFBC00>자동 전투</COLOR>버튼을 눌러 자동전투 기능을 사용할 수 있습니다.\n자동 전투 시 아군 함선은 <COLOR=#FFBC00>배치 된 순서대로 이동</COLOR>하며, \n긴급복구로 복구된 함선이 있다면 마지막으로 이동합니다."
L23_1[1] = L24_1
L23_1[2] = L25_1
