L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_PF_TUTORIAL_TEXUTRE_WARFARE_AUTOPLAY_2_DESC"
L30_1 = "자동 보급 옵션이 켜져 있다면, 전역에 <COLOR=#FFBC00>남은 적 수 </COLOR>에 따라 각 함선은 자동으로 탄환 보급을 합니다.\n단, 어떤 소대가 승리 할지 모르기 때문에 탄환 보급 판단은 <COLOR=#FFBC00>소대 별로 수행</COLOR>합니다."
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_PF_TUTORIAL_TEXUTRE_WARFARE_AUTOPLAY_3_DESC"
L31_1 = "<COLOR=#FFBC00>자동 보급 옵션</COLOR>이 꺼져있다면, 자동 전투 시 보급을 하지 않습니다.\n보스/타겟 처치 전역의 경우 탄환을 다 사용 하였다면, <COLOR=#FFBC00>퇴각</COLOR>을 하게 되며 이로인한 애사심 하락은 없습니다.\n도착/점령 전역의 경우 탄환을 다 사용 하더라도 목적지로 계속해서 <COLOR=#FFBC00>이동을 시도</COLOR>합니다."
L29_1[1] = L30_1
L29_1[2] = L31_1
