L33_1 = "SI_PF_TUTORIAL_TEXUTRE_WARFARE_CONTAINER_1_DESC"
L34_1 = "전역에서 <COLOR=#FFBC00>컨테이너가 위치한 타일</COLOR>로 <COLOR=#FFBC00>소대를 이동</COLOR>하여 <COLOR=#FFBC00>컨테이너를 회수</COLOR>하면,\n전역 승리 시 <COLOR=#FFBC00>추가적인 승리 보상</COLOR>을 얻습니다.\n전역을 패배하거나 이탈하면 컨테이너 보상을 얻지 못합니다."
L32_1[1] = L33_1
