L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_PF_TUTORIAL_TEXUTRE_WARFARE_CONTROL_1_DESC"
L37_1 = "전역은 편성된 소대를 이용하는 전략 전투 모드 입니다.\n전역에서는 아군과 적이 번갈아 가며 페이즈를 수행하며,\n<COLOR=#FFBC00>한 페이즈에 소대 당 1회 이동</COLOR>할 수 있고, <COLOR=#FFBC00>적과 조우하면 전투에 진입</COLOR>합니다."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
