L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_PF_TUTORIAL_TEXUTRE_SHADOW_PALACE_BATTLE_DESC"
L19_1 = "그림자 전당에서는 클리파에서 파생된 강력한 도플갱어와 침식체들이 등장합니다.\n\n그림자 전당에서 발생하는 전투는 <COLOR=#FFBC00>일부 유닛 혹은 클래스의 출격이 제한</COLOR>되며, 제한 요소는 팔레스와 룸마다 서로 다릅니다."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_PF_TUTORIAL_TEXUTRE_SHADOW_PALACE_INFO_TITLE"
L20_1 = "그림자 전당"
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_PF_TUTORIAL_TEXUTRE_SHADOW_PALACE_INFO_DESC_01"
L21_1 = "그림자 전당은 클리파와 연결된 위험한 통로입니다.\n위험한 침식체들이 현실세계로 부상하기 전에, 진압해야 합니다."
