L23_1 = "SI_PF_TUTORIAL_TEXUTRE_SHADOW_PALACE_INFO_DESC_02"
L24_1 = "그림자 전당의 팔레스에 입장하기 위해서는 <COLOR=#FFBC00>양자좌표석</COLOR>이 필요합니다.\n양자좌표석은 <COLOR=#FFBC00>매일 오전 4시</COLOR>에 1개씩 보급됩니다.\n<COLOR=#FFBC00>보유 중인 양자좌표석이 7개 이상일 경우, 보급 받을 수 없습니다.</COLOR>"
