L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_PF_TUTORIAL_TEXUTRE_SHADOW_PALACE_RANK_DESC"
L26_1 = "그림자 전당의 팔레스 공략 성공 시, 전투 기록이 랭킹에 등록됩니다.\n<COLOR=#FFBC00>룸 별 전투 기록은 팔레스 공략 최고기록 시에 달성한 시간으로 등록</COLOR>되며, 기록을 확인 할 수 있습니다.\n\n그림자 전당의 공략을 최적화 하여, 최고의 기업임을 입증해 보세요."
