L32_1 = "SI_PF_TUTORIAL_TEXUTRE_SUPPLY_OPERATION_01_DESC_01"
L33_1 = "보급작전은 회사와 유닛 성장에 필요한 물품들을 집중적으로 얻을 수 있는 작전입니다.\n보급작전은 <COLOR=#FFBC00>메인스트림 / 자유계약 등 특정 스테이지</COLOR>를 클리어 하는 것으로 작전 리스트를 확장 할 수 있습니다."
