L2_1 = "SI_PF_TUTORIAL_TEXUTRE_FIERCE_01_TEXT"
L3_1 = "격전지원의 입장 횟수는 모든 보스 및 단계에서 공유되며,\n특정 보스에 사용된 함선 / 유닛 / 장비는 다른 보스에서 사용 할 수 없습니다"
