L3_1 = "SI_PF_TUTORIAL_TEXUTRE_FIERCE_02_DESC_01"
L4_1 = "격전지원의 보스를 공략하는데 사용한 <COLOR=#FFBC00>유닛 / 함선 / 장비</COLOR> 는 다른 보스에서 사용 할 수 없습니다."
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_PF_TUTORIAL_TEXUTRE_FIERCE_02_DESC_02"
L5_1 = "격전지원의 <COLOR=#FFBC00>입장 횟수</COLOR>와  <COLOR=#FFBC00>사용한 덱 정보</COLOR>는 <COLOR=#FFBC00>전투 종료를 기준으로 소모 및 등록</COLOR> 됩니다."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_PF_TUTORIAL_TEXUTRE_FIERCE_03_DESC_01"
L6_1 = "격전지원의 포인트 보상은 섬멸 점수 갱신에 따라 보상 획득이 가능합니다.\n격전지원이 진행 중인 섬멸 기간과 결산 기간 동안 <COLOR=#FFBC00>수령하지 않은 보상은 사라집니다.</COLOR>\n"
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_PF_TUTORIAL_TEXUTRE_FIERCE_03_POINT"
L7_1 = "섬멸 점수 보상"
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_PF_TUTORIAL_TEXUTRE_FIERCE_03_DESC_02"
L8_1 = "수령하지 않은 보상은 점수 초기화 시 비활성화 되며,\n<COLOR=#FFBC00>한번 수령한 보상은 초기화 하더라도 다시 받을 수 없습니다.</COLOR>\n"
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_PF_TUTORIAL_TEXUTRE_FIERCE_04_DESC_01"
L9_1 = "격전지원의 랭킹 보상은 달성한 랭킹에 따라 보상 획득이 가능합니다.\n랭킹 보상은 결산 기간 동안 격전지원 메인메뉴에서 수령할 수 있으며, <COLOR=#FFBC00>수령하지 않은 보상은 사라집니다.</COLOR>\n"
L7_1[1] = L8_1
L7_1[2] = L9_1
