L15_1 = "최근 일정 기간 내의 픽률과 승리횟수가 낮은 유닛들 중 일부를 업 대상으로 선정합니다.\n업 대상은 매주마다 진행하며, <COLOR=#FFBC00>밴 유닛은 업 대상에 포함되지 않습니다.</COLOR>"
