L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_PF_TUTORIAL_TEXUTRE_OPERATOR_INFO_1_DESC"
L24_1 = "오퍼레이터는 전투에 참여해 함선과 소대원을 보조하는 유닛입니다."
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_PF_TUTORIAL_TEXUTRE_OPERATOR_INFO_2_DESC"
L25_1 = "각 소대마다 1명의 오퍼레이터를 편성할 수 있습니다."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_PF_TUTORIAL_TEXUTRE_OPERATOR_INFO_3_DESC"
L26_1 = "편성한 오퍼레이터의 능력치에 비례하여 <COLOR=#FFBC00>함선의 능력치가 상승</COLOR>합니다."
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_PF_TUTORIAL_TEXUTRE_OPERATOR_INFO_4_DESC"
L27_1 = "<COLOR=#FFBC00>오퍼레이터 전술 자료</COLOR> 아이템과 크레딧으로 오퍼레이터의 레벨을 올려 \n능력치를 더욱 더 상승시킬 수 있습니다."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_PF_TUTORIAL_TEXUTRE_OPERATOR_SKILL_1_TITLE"
L28_1 = "지휘 기술"
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_PF_TUTORIAL_TEXUTRE_OPERATOR_SKILL_2_TITLE"
L29_1 = "보조 기술"
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_PF_TUTORIAL_TEXUTRE_OPERATOR_SKILL_1_DESC"
L30_1 = "조건에 해당하는 유닛을 <COLOR=#FFBC00>순서대로</COLOR> 내면 <COLOR=#FFBC00>지휘 기술</COLOR>이 발동됩니다.\n조건에 해당하지 않는 유닛을 도중에 출격 시켜도, 연계 이력은 초기화되지 않습니다.\n단, <COLOR=#FFBC00>시간 게이지</COLOR>가 소진될 때 까지 전부 내지 못하면 연계 이력은 초기화됩니다."
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_PF_TUTORIAL_TEXUTRE_OPERATOR_SKILL_2_DESC"
L31_1 = "보조 기술은 전투 중 유지되는 패시브 효과입니다.\n오퍼레이터 <COLOR=#FFBC00>획득 시점에 무작위로 결정</COLOR>되며, \n동일 오퍼레이터라도 서로 다른 보조 기술을 가질 수 있습니다."
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_PF_TUTORIAL_TEXUTRE_OPERATOR_COMPOSE_1_TITLE"
L32_1 = "오퍼레이터 합성"
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_PF_TUTORIAL_TEXUTRE_OPERATOR_COMPOSE_2_TITLE"
L33_1 = "지휘 기술 및 보조 기술의 전수"
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_PF_TUTORIAL_TEXUTRE_OPERATOR_COMPOSE_3_TITLE"
L34_1 = "보조 기술 변경"
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "SI_PF_TUTORIAL_TEXUTRE_OPERATOR_COMPOSE_1_DESC"
L35_1 = "오퍼레이터를 재료로 투입해 <COLOR=#FFBC00>기술을 성장</COLOR>시키거나 <COLOR=#FFBC00>다른 기술로 변경</COLOR>할 수 있습니다."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_PF_TUTORIAL_TEXUTRE_OPERATOR_COMPOSE_2_DESC"
L36_1 = "<COLOR=#FFBC00>동일한 기술을 보유하고 있는 오퍼레이터</COLOR>를 재료로 투입 시, 기술의 레벨이 상승합니다.\n재료 오퍼레이터의 등급이 높을 수록 성공률이 높고, 실패해도 기존 기술의 레벨은 유지됩니다.\n재료 오퍼레이터는 합성 시점에 성공 여부에 관계 없이 소진됩니다."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_PF_TUTORIAL_TEXUTRE_OPERATOR_COMPOSE_3_DESC"
L37_1 = "<COLOR=#FFBC00>서로 다른 보조 기술을 보유한 오퍼레이터</COLOR>를 재료로 투입해, 원하는 보조 기술로 변경할 수 있습니다.\n보조 기술을 변경하고 싶은 오퍼레이터와 <COLOR=#FFBC00>등급이 같거나 높은 오퍼레이터만 재료로 사용 가능</COLOR>합니다.\n<COLOR=#FFBC00>보조 기술 변경 버튼을 ON으로 활성화</COLOR> 한 경우에만 보조 기술 변경이 이루어집니다.\n보조 기술 변경 성공 시, <COLOR=#FFBC00>기존의 보조 기술 레벨은 1단계로 초기화</COLOR> 됩니다."
L35_1[1] = L36_1
L35_1[2] = L37_1
