L41_1 = "SI_PF_TUTORIAL_TEXUTRE_GUILD_INFORMATION_TITLE"
L42_1 = "컨소시엄"
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_PF_TUTORIAL_TEXUTRE_GUILD_INFORMATION_DESC"
L43_1 = "컨소시엄은 <COLOR=#FFBC00>다수의 기업이 모인 협력체</COLOR>입니다.\n컨소시엄 공동의 목표를 달성하고, 성장시켜\n다양한 보상을 획득할 수 있습니다."
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_PF_TUTORIAL_TEXUTRE_GUILD_LEVELUP_1_TITLE"
L44_1 = "기부"
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_PF_TUTORIAL_TEXUTRE_GUILD_LEVELUP_1_DESC"
L45_1 = "보유하고 있는 연합의 증표, 크레딧, 쿼츠를 소모하여 컨소시엄 경험치를 획득할 수 있습니다.\n기부를 통해 소모한 <COLOR=#FFBC00>자원만큼 다양한 혜택으로 돌려받으실 수 있습니다.</COLOR>\n기부는 매일 오전 4시부터 3회 가능합니다."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_PF_TUTORIAL_TEXUTRE_GUILD_LEVELUP_1_TEXT_01"
L46_1 = "재화 기부"
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_PF_TUTORIAL_TEXUTRE_GUILD_LEVELUP_1_TEXT_02"
L47_1 = "컨소시엄 경험치"
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_PF_TUTORIAL_TEXUTRE_GUILD_LEVELUP_2_TITLE"
L48_1 = "주간 미션"
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "SI_PF_TUTORIAL_TEXUTRE_GUILD_LEVELUP_2_DESC"
L49_1 = "컨소시엄에서 제공한 다양한 미션을 클리어하여 컨소시엄 경험치를 획득할 수 있습니다.\n<COLOR=#FFBC00>연합의 증표를 획득하여, 연합 상점에서 다양한 물품으로 교환</COLOR>할 수 있습니다."
L47_1[1] = L48_1
L47_1[2] = L49_1
