L50_1 = "SI_PF_TUTORIAL_TEXUTRE_GUILD_WELFARE_1_DESC"
L51_1 = "매주 월요일 오전 4시마다 컨소시엄 레벨에 따라 복지 포인트를 제공받습니다.\n<COLOR=#FFBC00>수령한 복지 포인트로 원하는 버프를 활성화</COLOR>시켜 혜택을 누릴 수 있습니다."
