L3_1 = "SI_PF_TUTORIAL_TEXUTRE_GUILD_WELFARE_2_TITLE"
L4_1 = "연합 버프"
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_PF_TUTORIAL_TEXUTRE_GUILD_WELFARE_2_DESC"
L5_1 = "기부 · 주간 미션등을 통해 획득한 <COLOR=#FFBC00>연합 공동 기금으로 컨소시엄 소속된 전체에게 혜택을 제공</COLOR>합니다.\n모두가 함께 협력하여 최상의 복지 혜택을 누려보세요!"
