L6_1 = "SI_PF_TUTORIAL_TEXUTRE_GUILD_DUNGEON_1_TITLE"
L7_1 = "컨소시엄 협력전"
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_PF_TUTORIAL_TEXUTRE_GUILD_DUNGEON_1_DESC"
L8_1 = "《컨소시엄 협력전》은 연합원과 함께 <COLOR=#FFBC00>방치되었던\n침식지대를 정화하는 협동형 컨텐츠</COLOR>입니다.\n주간 1회 진행되며, 각 정화작전은 5일간\n진행됩니다."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_PF_TUTORIAL_TEXUTRE_GUILD_DUNGEON_2_TITLE"
L9_1 = "아레나 정화도"
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_PF_TUTORIAL_TEXUTRE_GUILD_DUNGEON_2_DESC"
L10_1 = "한 정화작전마다 각 연합원에게 5번의 아레나 입장 횟수가 주어집니다.\n<COLOR=#FFBC00>아레나를 클리어하면 획득한 메달 개수만큼 정화도가 쌓이며,</COLOR>정화도가 가득 찰 때마다 아티팩트가 지급됩니다."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_PF_TUTORIAL_TEXUTRE_GUILD_DUNGEON_3_TITLE"
L11_1 = "레이드"
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_PF_TUTORIAL_TEXUTRE_GUILD_DUNGEON_3_TITLE_DESC"
L12_1 = "한 정화작전마다 각 연합원에게 5번의 레이드 입장 횟수가 주어집니다.\n<COLOR=#FFBC00>아레나에서 획득한 아티팩트를 조합</COLOR>해, 소대를 더욱 강하게 만들어 투입시킬 수 있습니다.\n보스의 광폭화 단계에 따라 높은 체력과 공격력, 방어력을 지니게 됩니다."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_PF_TUTORIAL_TEXUTRE_GUILD_DUNGEON_4_TITLE"
L13_1 = "보상"
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_PF_TUTORIAL_TEXUTRE_GUILD_DUNGEON_4_DESC"
L14_1 = "정화작전이 종료되면, <COLOR=#FFBC00>보스 처치에 따라 보상을 획득</COLOR>하실 수 있습니다.\n또한, <COLOR=#FFBC00>시즌동안 누적된 성적에 따라 시즌 보상을 획득</COLOR>하실 수 있습니다."
