L28_1 = {}
L29_1 = "SI_PF_TUTORIAL_TEXUTRE_CHALLENGE_OPERATION_1_DESC_01"
L30_1 = "[챌린지]는 고난이도의 도전형 컨텐츠 입니다.\n챌린지 스테이지는 입장에 <COLOR=#FFBC00>[챌린지 티켓]</COLOR>이 필요합니다.\n<COLOR=#FFBC00>챌린지 티켓은 매일 1장씩 보급되며, 보유중인 챌린지 티켓이 10장 이상이라면 보급 받을 수 없습니다.\n</COLOR>"
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_PF_TUTORIAL_TEXUTRE_CHALLENGE_OPERATION_1_DESC_02"
L31_1 = "챌린지 스테이지에는 <COLOR=#FFBC00>최초 클리어 보상</COLOR>과 <COLOR=#FFBC00>3메달 완수 보상</COLOR>이 존재하며,\n클리어 시 챌린지 메달과 고가치의 장비 / 소모품 을 획득 할 수 있습니다."
