L33_1 = "SI_PF_TUTORIAL_TEXUTRE_CHALLENGE_OPERATION_2_DESC"
L34_1 = "챌린지 메달은 챌린지 상점에서 일부 아이템을 구매하는데 사용되며,\n챌린지 티켓을 교환하여, 소량의 챌린지 메달을 획득 할 수 도 있습니다."
