L40_1 = {}
L41_1 = "SI_PF_TUTORIAL_TEXUTRE_RACE_RUNNING_1_DESC_01"
L42_1 = "두 팀 중 한 팀을 선택하여 경주를 진행합니다.\n미션을 수행하여 얻은 아이템을 사용해 경주에 참여할 수 있습니다.\n경주는 일일 최대 3회 참여 가능합니다.\n경주 참여 가능 횟수와 선택한 팀은 매일 오전 4시에 초기화됩니다.\n경주 결과에 따라 보상 및 팀 점수를 얻습니다.\n매일 오전 4시마다 팀 점수를 더 많이 획득한 팀이 승리하며,\n보상을 획득합니다."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_PF_TUTORIAL_TEXUTRE_RACE_RUNNING_1_DESC_02"
