L45_1 = {}
L46_1 = "SI_PF_TUTORIAL_TEXUTRE_RACE_INFORMATION_1_DESC_01"
L47_1 = "두 라인 중 하나를 선택하여 경주를 진행합니다.\n경주를 진행하며 만나는 장애물에 따라 방해를 받거나 도움을 받습니다.\n경주에서 승리하면 팀 점수 3점, 패배하면 팀 점수 1점이 부여됩니다.\n선택한 팀이 승리하도록 응원해주세요! "
