L2_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_LEAGUE_1_DESC"
L3_1 = "리그전은 <COLOR=#FFBC00>랭크전 점수 3000점 이상</COLOR> 달성 시 개방됩니다.\n리그전은 전략전 / 랭크전과 별도의전적과 티어로 운영됩니다."
