L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_LEAGUE_2_DESC_00"
L6_1 = "리그전은 매칭 후, 소대 편성이 진행됩니다.\n편성 시, 플레이어와 상대방이 <COLOR=#FFBC00>번갈아가면서 유닛을 선택</COLOR>하며,\n<COLOR=#FFBC00>중복 유닛</COLOR>은 사용할 수 없습니다."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_LEAGUE_2_DESC_01"
L7_1 = "편성을 시작하고 끝마치는 시점에서,\n<COLOR=#FFBC00>사용 금지 유닛</COLOR>을 지정 할 수 있습니다."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_LEAGUE_3_TEXT_00"
L8_1 = "건틀렛 포인트"
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_LEAGUE_3_TEXT_01"
L9_1 = "명예 보상"
