L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_LEAGUE_2_DESC"
L10_1 = "리그전 승리 시, <color=#FFBC00>건틀렛 포인트</color>를 획득할 수 있습니다.\n리그전은 주간 결산이 없으며, 시즌 최종 결산 시 <color=#FFBC00>명예 보상</color>을 획득할 수 있습니다."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_PF_TUTORIAL_TEXUTRE_DIVE_SEARCH_2_TITLE"
L11_1 = "강습전"
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_PF_TUTORIAL_TEXUTRE_DIVE_SEARCH_2_DESC"
L12_1 = "클리어한 단계에 재진입할 때에는, 강습전을 발동할 수 있습니다.\n<COLOR=#FFBC00>강습전으로 탐사 진행시, 해당 탐사 좌표의 침식 코어를 곧바로 상대</color>할 수 있습니다.\n클리어 시, 해당 단계의 보상을 획득할 수 있으며 추가로 강습 보너스를 얻을 수 있습니다."
L10_1[1] = L11_1
L10_1[2] = L12_1
