L14_1 = "본사 개요"
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_PF_TUTORIAL_TEXUTRE_OFFICE_INFO_1_DESC"
L15_1 = "드디어 코핀 컴퍼니의 본사가 완공되었습니다. \n본사에는 사원들이 머물 수 있는 기숙사와 각종 업무 시설들이 배치되어 있습니다."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_PF_TUTORIAL_TEXUTRE_OFFICE_INFO_2_TITLE"
L16_1 = "본사 미니맵"
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_PF_TUTORIAL_TEXUTRE_OFFICE_INFO_2_DESC"
L17_1 = "미니맵을 통해 본사의 각종 시설들과 기숙사를 오갈 수 있습니다. \n사원의 배치와 기숙사의 추가 구매도 가능합니다."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_PF_TUTORIAL_TEXUTRE_OFFICE_DORMI_1_TITLE"
L18_1 = "기숙사 인테리어"
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_PF_TUTORIAL_TEXUTRE_OFFICE_DORMI_1_DESC"
L19_1 = "기숙사 내부에 가구들을 배치할 수 있습니다. 가구는 상점 및 각종 보상들로 획득 가능합니다. \n벽지, 바닥, 배경은 1개만 가지고 있어도 여러 방에 중복 배치가 가능하나, 일반 가구의 경우 동일 가구를 여러 개 가지고 있어야 가능합니다."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_PF_TUTORIAL_TEXUTRE_OFFICE_DORMI_2_TITLE"
L20_1 = "애사심"
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_PF_TUTORIAL_TEXUTRE_OFFICE_DORMI_2_DESC"
L21_1 = "각 방의 환경 점수에 따라 배치된 사원들의 애사심 게이지가 차오르며, 게이지가 가득 찼을 때 하트를 터치하면 애사심이 1 올라갑니다.\n배치한 가구의 크기가 클 수록, 등급이 높을 수록 환경 점수가 높으며, 환경 점수 총합이 높을 수록 사원들의 애사심이 더 빠르게 올라갑니다."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_PF_TUTORIAL_TEXUTRE_OFFICE_DORMI_3_TITLE"
