L22_1 = "SI_PF_TUTORIAL_TEXUTRE_OFFICE_DORMI_3_DESC"
L23_1 = "협력사 또는 다른 사장님들의 기숙사에 방문할 수 있습니다. 명함을 주고받으며 긴밀한 협력 관계를 유지해 보세요.\n획득한 명함은 협력사의 명함으로 교환되어 채용에 활용할 수 있습니다. 기숙사에서는 하루에 최대 500장까지만 획득이 가능합니다."
L21_1[1] = L22_1
L21_1[2] = L23_1
