L24_1 = "SI_PF_TUTORIAL_TEXUTRE_OFFICE_DORMI_4_DESC"
L25_1 = "[코핀 컴퍼니 법인 카드] 아이템을 사용하여 기숙사에서 회식을 진행할 수 있습니다. \n회식 진행 시 기숙사에 배치된 사원의 <COLOR=#FFBC00>애사심</color>이 오르며 추가적인 보상을 획득합니다. \n<COLOR=#FFBC00>[코핀 컴퍼니 법인 카드]는 1일 1회 충전</color>되며 상점에서 <COLOR=#FFBC00>일정 횟수 추가로 구매 가능</color>합니다."
