L41_1 = "SI_PF_TUTORIAL_TEXUTRE_REARM_INFO_1_DESC"
L42_1 = "재무장을 통해 110레벨까지 육성시킨 사원을 추가로 성장시킬 수 있습니다. \n재무장 진행 시 사원의 역할군이 추가 및 변경될 수 있으며, 레벨 1로 초기화됩니다. \n재무장에는 융합핵 및 크레딧, 특수적성핵, 적성핵이 필요합니다. \n※ 재무장은 연구소에서 진행하실 수 있습니다. "
