L4_1 = " \n연구소에 데이터 전송실 설비가 준비되었습니다. \n사원의 정보를 전송하여 재무장에 필요한 [재무장 데이터]를 획득할 수 있습니다. \n※ 데이터 전송을 완료한 사원은 사라집니다."
