L8_1 = "공방에서 <COLOR=#FFBC00>일부 T6 이상의 SSR 유니크 장비와 전용장비</color>를 업그레이드 할 수 있습니다. \n업그레이드 시, 이전 장비의 튜닝 정보와 정밀화 수치, 강화 경험치는 <COLOR=#FFBC00>유지</color>됩니다. \n업그레이드에 필요한 소재들은 <COLOR=#FFBC00>챌린지</color>에서 획득 할 수 있습니다."
