L11_1 = "잠재개방을 통해, 렐릭 장비를 한층 더 강화 시킬 수 있습니다. \n렐릭 장비의 소켓 별 잠재옵션을 개방하기 위해서는 <COLOR=#FFBC00>각 소켓의 강화단계 조건을 충족</color>해야 합니다. \n한번 결정된 잠재옵션은 변경 할 수 없습니다."
