L21_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_FRIENDLY_4_DESC"
L22_1 = "장비와 성장으로 증가한 체력, 공격력, 방어력의 10%만 적용됩니다.\n함선 등급에 따라 증가하는 기초 출격자원이 적용되지 않습니다.\n시즌 룰과 밴&업 영향을 받지 않습니다.\n<COLOR=#FFBC00>옵션 설정 여부에 따라, 장비 능력치와 밴&업 영향은 변경될 수 있습니다.</COLOR>"
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_FRIENDLY_5_DESC"
L23_1 = "친선전에서는 옵션을 ON 또는 OFF로 설정하여 대결할 수 있습니다.\n초대를 보낸 유저의 옵션 설정을 따릅니다.\n친선전 전투 진입 후, 옵션이 반영됩니다."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_PF_TUTORIAL_TEXUTRE_WORLDMAP_BUILD_LIMIT_1_DESC_02"
L24_1 = "동시 설치 불가"
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_PF_TUTORIAL_TEXUTRE_BAR_TITLE"
L25_1 = "<COLOR=#FFBC00>니콜의 VIP 출장 칵테일 서비스</color>"
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_PF_TUTORIAL_TEXUTRE_BAR_DELIVERY_TITLE_01"
L26_1 = "그레모리에게 칵테일 전달"
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_PF_TUTORIAL_TEXUTRE_BAR_DELIVERY_DESC_01"
L27_1 = "[니콜의 VIP 출장 칵테일 서비스]에서는 이벤트 기간 중 그레모리에게 칵테일을 건네줄 수 있습니다.\n- 그레모리가 원하는 칵테일과 그 보상은 매일 달라집니다. \n- 그레모리에게 전달할 칵테일은 다음 방법을 통해서 획득할 수 있습니다.\n   - <color=#ffbc00>[모모에게 심부름]</color>에서 칵테일 재료를 얻을 수 있습니다.\n   - <color=#ffbc00>[니콜의 칵테일 제조]</color>에서 칵테일을 제조할 수 있습니다."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_PF_TUTORIAL_TEXUTRE_BAR_ERRAND_TITLE_01"
L28_1 = "모모에게 심부름"
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_PF_TUTORIAL_TEXUTRE_BAR_ERRAND_DESC_01"
L29_1 = "[모모에게 심부름]에서는 이벤트 기간 중 모모에게 심부름을 시킬 수 있습니다.\n - 제시되는 미션의 보상으로 <color=#ffbc00>[달콤한 공물]</color>을 얻게 됩니다. \n - <color=#ffbc00>[달콤한 공물]</color>을 모으면 모모에게 심부름을 시킬 수 있습니다.\n - 심부름으로 <color=#ffbc00>[칵테일 재료]</color>를 얻을 수 있습니다."
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_PF_TUTORIAL_TEXUTRE_BAR_MAKING_TITLE_01"
L30_1 = "니콜의 칵테일 제조"
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_PF_TUTORIAL_TEXUTRE_BAR_MAKING_DESC_01"
L31_1 = "[니콜의 칵테일 제조]에서는 각기 다른 재료와 기법으로 총 6종의 칵테일을 제조할 수 있습니다.\n - 칵테일 재료가 부족하면, 모모에게 심부름을 보내거나 상점에서 구매할 수 있습니다.\n - <color=#ffbc00>제작한 칵테일은 그레모리에게 전달하거나 칵테일을 [사용]해서 보상을 얻을 수 있습니다.</color>"
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_ASYNC_1_DESC_01"
L32_1 = "전략전에서는 <COLOR=#FFBC00>비동기로 대전</COLOR>할 수 있습니다.\n<COLOR=#FFBC00>상대의 방어 소대</COLOR>와 전투합니다.\n승리하면 승점을 얻지만, 패배하면 승점을 잃습니다."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_ASYNC_4_TEXT_01_1"
L33_1 = "방어소대의 일부 유닛은 다른 유저에게 비공개됩니다."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_ASYNC_4_DESC_01"
L34_1 = "전략전에 참여하려면 <COLOR=#FFBC00>방어소대를 설정</COLOR>해야합니다.\n방어소대는 다른 회사의 공격을 막아내고, 버프와 밴&업 영향을 받습니다.\n방어전에 승리하면 <COLOR=#FFBC00>건틀렛 포인트를 보상</COLOR>으로 받을 수 있습니다.\n방어전에 패배하면 승점이 감소하며, 일정 횟수부터는 감소하지 않습니다."
L32_1[1] = L33_1
