L40_1 = "대표적으로 알려진 4종 침식체. 앙상하고 긴 팔다리에 뇌전을 두른 거인의 형상으로 나타난다. 붕대에 가려진 얼굴은 시련과 마주한 수도사처럼 창백하고 경직되어 있다."
