L43_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_RAID_DESC_01_01"
L44_1 = "브리트라는 기본 공격으로 광역 피해를 줍니다.\n함선 직접 타격 스킬을 사용하기에 함선을 육성하시기를 추천합니다."
