L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_RAID_DESC_01_02"
L45_1 = "레이드 시작 후 이동 속도가 높은 <COLOR=#FFBC00>침식체가 다수 등장</COLOR>합니다."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_RAID_DESC_01_03"
L46_1 = "브리트라는 <COLOR=#FFBC00>전투 종료 1분 20초 전, 배리어와 함께 힘을 모읍니다.</COLOR>\n브리트라가 <COLOR=#FFBC00>힘을 모으는 동안 공격을 집중하여 저지</COLOR>해야 합니다.\n저지하지 못하면 사원과 함선에 큰 피해를 입힙니다.\n저지하면 잠시 스턴 상태에 빠지며 이때 공격을 집중해 큰 피해를 줄 수 있습니다.\n※ 해당 패턴은 <COLOR=#FFBC00>브리트라의 전체 체력이 85% 이하일 때만 발동</COLOR>합니다.\n※ 레벨에 따라 체력에 비례한 배리어가 생성됩니다."
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_RAID_UNIT_01_01"
L47_1 = "전방에 <COLOR=#FFBC00>[높은방어]</COLOR> 태그를 지닌 사원을 배치 후 원거리 공격 사원을 배치하여 광역 공격에 대비하시기 바랍니다."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_RAID_UNIT_01_02"
L48_1 = "<COLOR=#FFBC00>[높은 체력]</COLOR> 또는 <COLOR=#FFBC00>[범위공격]</COLOR> 태그를 지닌 사원을 시작과 함께 출격하여 침식체를 막으시기를 바랍니다."
