L4_1 = "뇌명 브리트라 : [악몽]은 상시로 <COLOR=#FFBC00>받는 회복량이 감소하는 디버프 영역을 생성</COLOR>합니다.\n기본 공격으로 광역 피해를 줍니다.\n함선 직접타격 스킬을 사용하기에 함선 육성하시기를 추천합니다."
