L15_1 = "레이저 패턴"
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_RAID_DESC_03_01"
L16_1 = "악몽 난이도 인히비터의 외형은 붉은색으로 변경됩니다."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_RAID_DESC_03_02"
L17_1 = "레이드 시작과 함께 더 월이 등장하여 가드 상태를 유지합니다.\n<COLOR=#FFBC00>더 월은 가드 상태에서는 피해를 보지 않습니다.</COLOR>\n더 월의 <COLOR=#FFBC00>가드는 푸른색 게이지가 모두 차오르기 전에 일정 횟수 타격을 입혀 해제</COLOR>할 수 있습니다."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_RAID_DESC_03_03"
L18_1 = "<COLOR=#FFBC00>전투 종료 2분 전, 소각 시스템이 기동하여 함선 안쪽을 제외한 지역의 사원들에게 높은 피해를</COLOR>줍니다.\n※ <COLOR=#FFBC00>소각 이후 인히비터에게 해제 불가능한 영구 피해 감쇄 -80% 버프가 적용</COLOR>됩니다."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_RAID_DESC_03_04"
L19_1 = "인히비터는 <COLOR=#FFBC00>전투 종료 35초 전, 레이저를 발사하여 모든 사원에 큰 피해</COLOR>를 줍니다.\n※ 레이저에 <COLOR=#FFBC00>피해를 입은 사원의 배리어는 해제</COLOR>됩니다."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_RAID_UNIT_03_01"
L20_1 = "<COLOR=#FFBC00>메카닉 타입에 디버프를 주는 사원</COLOR>을 편성하는 것을 추천합니다."
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_RAID_UNIT_03_02"
L21_1 = "<COLOR=#FFBC00>[물량 공세]</COLOR> 또는 <COLOR=#FFBC00>[빠른 공격]</COLOR> 태그를 보유한 사원을 편성하여 더 월의 가드를 빠르게 해제할 수 있습니다"
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_RAID_UNIT_03_03"
L22_1 = "아군 사원 전멸 이후 <COLOR=#FFBC00>[코스트 회복]</COLOR> 태그를 보유한 사원을 통해 빠르게 전열을 정비할 수 있습니다."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_RAID_UNIT_03_04"
L23_1 = "<COLOR=#FFBC00>아군에게 피해 감소 버프를 부여하는 사원을 편성</COLOR>하여 피해를 버티시기를 바랍니다."
L21_1[1] = L22_1
L21_1[2] = L23_1
