L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_GUILD_INFO_01"
L30_1 = "캄파멘토 인근의 부유섬에 출몰하는 4종 침식체. 암석 같은 갑피로 중무장한 이 대형 환형동물은 일확천금을 노리던 수많은 탐험자들을 바닥 없는 구덩이에 매장해 버렸다."
