L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_GUILD_DESC_01_01"
L36_1 = "데몰리션 웜은 <COLOR=#FFBC00>협력전 단계에 따라 사용하는 패턴 및 적용되는 버프가 변경</COLOR>됩니다.\n지역에는 일정 시간마다 소형 침식체가 등장합니다."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_GUILD_DESC_01_02"
L37_1 = "데몰리션 웜의 <COLOR=#FFBC00>전방과 후방 모든 지역에 사원을 출격</COLOR>시킬 수 있습니다.\n데몰리션 웜은 <COLOR=#FFBC00>사거리 내 사원이 더 많은 지역을 공격하며 반대 지역이 많아질 시 특수기를 사용</COLOR>합니다.\n※ 후방 지역에는 알이 있어 일정 시간이 지나면 부화하니 신속히 제거하시길 바랍니다."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_GUILD_DESC_01_03"
L38_1 = "데몰리션 웜이 <COLOR=#FFBC00>전투 종료 2분 전, 함선 방향으로 용암을 내뿜습니다.</COLOR>\n<COLOR=#FFBC00>바닥에 20초간 지속 피해를 주는 용암이 생성</COLOR>됩니다.\n용암이 생성된 후 공중 이동 타입 침식체가 다수 등장합니다."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_GUILD_DESC_01_04"
L39_1 = "데몰리션 웜이 <COLOR=#FFBC00>전투 종료 1분 전, 모든 사원을 함선 방향으로 몰고 스턴</COLOR>을 겁니다.\n그 후 <COLOR=#FFBC00>맵 오른쪽에서 출현하여 돌진하며 함선 쪽에 모인 사원을 모두 공격</COLOR>합니다.\n사원의 스턴이 해제되고 데몰리션 웜은 중앙에 출현합니다.\n※ 공중 이동 사원과 함선은 피해를 보지 않습니다.\n※ <COLOR=#FFBC00>돌진 도중 사원과 부딪힐 때마다 공격력이 감소</COLOR>합니다."
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_GUILD_DESC_01_05"
L40_1 = "데몰리션 웜에게 스킬 봉인 면역, 쿨타임 감소 면역, 피해 감쇄 버프가 부여되며 디버프 지속시간이 감소합니다.\n<COLOR=#FFBC00>기본 공격에는 사원의 영구 체력을 감소하는 디버프와 톱날 공격에는 방어력과 체력 회복량을 감소하는 디버프가 추가</COLOR>됩니다."
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_GUILD_UNIT_01_03"
L41_1 = "후방은 용암에 영향을 받지 않습니다.\n<COLOR=#FFBC00>후방에 사원을 적극 출격</COLOR>하세요.\n용암 패턴 이후 <COLOR=#FFBC00>공중 이동 타입의 사원을 배치하여 침식체의 공격을 막은 후 재정비</COLOR>하세요."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_GUILD_UNIT_01_04"
L42_1 = "아군 전체에게 피해감소 버프를 누적시켜 공격을 버틸 수 있도록 <COLOR=#FFBC00>피해 감소 버프를 부여하는 사원</COLOR>을 적극 사용하세요."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_GUILD_UNIT_01_05"
L43_1 = "<COLOR=#FFBC00>디버프를 해제할 수 있는 사원을 적극 사용</COLOR>하세요."
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_GUILD_INFO_02"
L44_1 = "학회의 영지를 배회하는 4종 침식체. 타이런트 타입의 상위종으로, 강철 같은 팔을 활용해 불청객들을 사냥한다. 19세기 말 추방되었다고 알려졌지만, 최근 다시 목격담이 잇따르고 있다."
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_GUILD_TITLE_MINI_02_01"
L45_1 = "보스 정보"
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
