L47_1 = "차지 공격 패턴"
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_GUILD_TITLE_MINI_02_04"
