L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_GUILD_DESC_02_01"
L49_1 = "타이런트 기가스는 기본적으로 <COLOR=#FFBC00>스킬 봉인 면역과 방어력 버프를 갖고 있습니다.</COLOR>\n방어력 버프는 1단계부터 50%가 적용되며 <COLOR=#FFBC00>단계에 올라갈수록 수치가 5%씩 증가</COLOR>합니다.\n타이런트 기가스는 <COLOR=#FFBC00>전 범위 공격, 특수기, 궁극기</COLOR>에서 <COLOR=#FFBC00>배리어가 있는 대상의 경우 배리어를 해제</COLOR>하고 피해를 입힙니다."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_GUILD_DESC_02_02"
L50_1 = "타이런트 기가스의 <COLOR=#FFBC00>좌측과 우측 모든 지역에 사원을 출격</COLOR>시킬 수 있습니다.\n타이런트 기가스는 <COLOR=#FFBC00>가까운 범위 내 적이 없을 시 전 범위에 공격을 실행</COLOR>합니다."
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_GUILD_DESC_02_03"
L51_1 = "타이런트 기가스는 <COLOR=#FFBC00>전투 종료 2분 전부터 특수기가 변화</COLOR>합니다.\n특수기를 사용할 시 <COLOR=#FFBC00>타이런트 아머를 소환해 적들의 앞을 막고, 자신은 강력한 차지 공격을 준비</COLOR>합니다.\n시간안에 저지하지 못하면 <COLOR=#FFBC00>전 범위에 강력한 공격을 시전</COLOR>합니다."
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
L51_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_GUILD_DESC_02_04"
L52_1 = "타이런트 기가스는 <COLOR=#FFBC00>전투 종료 1분전부터 자신 바로 아래에 적들에게 주기적으로 데미지를 주는 장판을 생성</COLOR>합니다.\n이후 타이런트 기가스의 <COLOR=#FFBC00>특수기가 적들을 중앙으로 모으는 공격으로 변화</COLOR>합니다."
L50_1[1] = L51_1
L50_1[2] = L52_1
