L7_1 = "SI_PF_TUTORIAL_TEXUTRE_SHIP_COMMANDMODULE_1_DESC"
L8_1 = "이식 개장을 진행한 함선은 <COLOR=#FFBC00>지휘 모듈</COLOR>을 설치할 수 있습니다.\n지휘 모듈은 <COLOR=#FFBC00>조건</COLOR>에 맞는 아군 사원들의 능력치를 증가시킵니다."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_PF_TUTORIAL_TEXUTRE_SHIP_COMMANDMODULE_2_TITLE"
L9_1 = "모듈 설치"
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_PF_TUTORIAL_TEXUTRE_SHIP_COMMANDMODULE_2_DESC"
L10_1 = "지휘 모듈은 이식 개장 단계마다 1개씩, <COLOR=#FFBC00>최대 3개까지 설치</COLOR>할 수 있습니다.\n설치되는 모듈의 소켓1은 사원의 <COLOR=#FFBC00>[타입]</COLOR>에만 적용되는 옵션이 랜덤하게 설정되며,\n소켓2는 사원의 <COLOR=#FFBC00>[클래스]</COLOR>에만 적용되는 옵션이 랜덤하게 설정됩니다.\n또한 모듈의 옵션은 비용을 소모하여 다시 <COLOR=#FFBC00>재설정</COLOR>할 수 있습니다."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_PF_TUTORIAL_TEXUTRE_SHIP_COMMANDMODULE_3_TITLE"
L11_1 = "소켓 잠금"
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_PF_TUTORIAL_TEXUTRE_SHIP_COMMANDMODULE_3_DESC"
L12_1 = "모듈의 소켓은 <COLOR=#FFBC00>반영구 기억장치</COLOR>를 소모하여 옵션을 <COLOR=#FFBC00>잠금</COLOR> 할 수 있습니다.\n잠금된 소켓의 옵션은 모듈을 <COLOR=#FFBC00>재설정</COLOR> 하더라도 옵션이 <COLOR=#FFBC00>변경되지 않습니다.</COLOR>\n※ 소켓의 잠금은 <COLOR=#FFBC00>해제</COLOR>할 수 있으나, 다시 잠금 하기 위해서는 똑같이 <COLOR=#FFBC00>반영구 기억장치</COLOR>를 소모해야 합니다."
L10_1[1] = L11_1
L10_1[2] = L12_1
