L13_1 = "SI_PF_TUTORIAL_TEXUTRE_TRIM_INFO_SUBTITLE"
L14_1 = "디멘션 트리밍은 그라운드 원에서 뻗어 나오는\n차원 균열 <COLOR=#FFBC00>[브랜치]</COLOR>의 확장을 저지하기 위한 원인 제거 활동입니다."
